def get_tunings(instrument=None, nr_of_strings=None, nr_of_courses=None):
    """Return a list of tunings.

    Can be filtered by instrument, number of strings, and/or number of courses.
    The instrument argument is treated as a case-insensitive prefix.

    Example:
    >>> get_tunings()
    [<StringTuning instance at 0x139ac20>, ...]
    >>> get_tunings('guitar')
    [<StringTuning instance at 0x139ac20>, ...]
    >>> get_tunings('guitar', 6, 1)
    [<StringTuning instance at 0x139ac20>, ...]
    """
    result = []

    if instrument is None:
        # Return all tunings
        for (instr_name, tunings_dict) in six.itervalues(_known):
            for tuning in six.itervalues(tunings_dict):
                if nr_of_strings is None and nr_of_courses is None:
                    result.append(tuning)
                elif nr_of_strings is not None and nr_of_courses is None:
                    if tuning.count_strings() == nr_of_strings:
                        result.append(tuning)
                elif nr_of_strings is None and nr_of_courses is not None:
                    if tuning.count_courses() == nr_of_courses:
                        result.append(tuning)
                else:
                    if (tuning.count_courses() == nr_of_courses and 
                        tuning.count_strings() == nr_of_strings):
                        result.append(tuning)
    else:
        # Filter by instrument
        searchi = str.upper(instrument)
        keys = list(_known.keys())
        for x in keys:
            if (searchi not in keys and x.find(searchi) == 0 or 
                searchi in keys and x == searchi):
                for tuning in six.itervalues(_known[x][1]):
                    if nr_of_strings is None and nr_of_courses is None:
                        result.append(tuning)
                    elif nr_of_strings is not None and nr_of_courses is None:
                        if tuning.count_strings() == nr_of_strings:
                            result.append(tuning)
                    elif nr_of_strings is None and nr_of_courses is not None:
                        if tuning.count_courses() == nr_of_courses:
                            result.append(tuning)
                    else:
                        if (tuning.count_courses() == nr_of_courses and 
                            tuning.count_strings() == nr_of_strings):
                            result.append(tuning)

    return result

